DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(p.oid) INTO def FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='trip_private' AND p.proname='ensure_sealed' AND pg_get_function_identity_arguments(p.oid)='p_trip uuid, p_user uuid'; IF def IS NULL OR position('sm.presentation_tag IS NULL' IN def)=0 OR position('IF t.season_rule=''a2c'' THEN' IN def)=0 THEN RAISE EXCEPTION 'Quest selector changed; aborting'; END IF; def:=replace(def,'sm.kind=''checkin'' AND sm.trip_id IS NULL AND sm.presentation_tag IS NULL','sm.kind=''checkin'' AND sm.trip_id IS NULL AND sm.presentation_tag IS NULL'); EXECUTE def; END $$;